function readSaved(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return v??fallback}catch{return fallback}}
function safeStore(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('فضای ذخیرهٔ مرورگر کافی نیست؛ تغییرات فقط تا بستن صفحه باقی می‌ماند.');return false}}
function normalizeCart(items){if(!Array.isArray(items))return [];const result=[];for(const c of items){if(!c||!Number.isSafeInteger(c.qty)||c.qty<1||c.qty>99)continue;const p=data.find(p=>p.id===c.product),v=p?.variants.find(v=>v.id===c.variant);if(!v)continue;const old=result.find(x=>x.variant===c.variant);if(old)old.qty=Math.min(99,old.qty+c.qty);else result.push({product:p.id,variant:v.id,qty:c.qty})}return result}
function cartValid(){const rows=cartItems();return rows.length>0&&rows.length===cart.length&&rows.every(c=>c.p.status==='published'&&c.v.published&&c.v.sale_enabled!==false&&Number.isSafeInteger(c.qty)&&c.qty>0&&c.qty<=Math.min(99,c.v.stock))}

