function locationOptions(province,selected=''){return (iranLocations[province]||[]).map(city=>`<option value="${esc(city)}" ${city===selected?'selected':''}>${esc(city)}</option>`).join('')}
function locationFields(){const province=checkoutDraft?.province||'',city=checkoutDraft?.city||'';return `<div class="field"><label for="province">استان</label><select id="province" name="province" required><option value="">انتخاب استان</option>${Object.keys(iranLocations).map(p=>`<option value="${esc(p)}" ${p===province?'selected':''}>${esc(p)}</option>`).join('')}</select><div class="error" id="err-province"></div></div><div class="field"><label for="city">شهر</label><select id="city" name="city" required ${province?'':'disabled'}><option value="">انتخاب شهر</option>${locationOptions(province,city)}</select><div class="error" id="err-city"></div></div>`}
const DEMO=!window.MARO?.server;const asset=n=>'assets/'+n;let data=[],cart=[],settings={shipping:650000,free_above:null,about:'مارو، انتخاب‌های کوچکی برای رنگی‌تر شدن روزهای معمولی. اینجا طرح‌های دوست‌داشتنی کنار هم جمع می‌شوند تا جفت موردعلاقه‌ات را پیدا کنی.',banner:'یه جفت حال خوب، برای هر روز',contact:'',shipping_policy:'',returns_policy:'',privacy_policy:'',terms_policy:'',size_guide:'',hero_image:''},filter={q:'',category:'همه',sort:'new',stock:false,color:'',size:'',min:'',max:''},adminTab='dashboard',selected=null,quantity=1,checkoutDraft=null,admin=false;
const demoProducts=[{id:1,name:'جوراب خرس تدی کریسمس',slug:'christmas-teddy-bear',category:'مناسبتی',description:'یک انتخاب قرمز و پرانرژی با طرح خرس تدی کریسمس. عکس واقعی محصول؛ مشخصات و قیمت نمونه‌اند.',image:'assets/red.webp',images:['assets/red.webp'],featured:true,status:'published',demo:true,variants:[{id:11,sku:'DEMO-RED-1',color:'قرمز',hex:'#a92932',size:'سایز نمونه A',price:1850000,stock:8,published:true},{id:12,sku:'DEMO-RED-2',color:'قرمز',hex:'#a92932',size:'سایز نمونه B',price:1850000,stock:3,published:true}]},{id:2,name:'جوراب خرس اسکی‌باز',slug:'ski-bear',category:'فانتزی',description:'قصهٔ کوچک یک روز برفی، با رنگ‌های آبی و سرمه‌ای. عکس واقعی محصول؛ مشخصات و قیمت نمونه‌اند.',image:'assets/blue.webp',images:['assets/blue.webp'],featured:true,status:'published',demo:true,variants:[{id:21,sku:'DEMO-BLUE-1',color:'آبی',hex:'#6b8b9d',size:'سایز نمونه A',price:1950000,stock:6,published:true}]},{id:3,name:'جوراب گل‌های کوچک',slug:'little-flowers',category:'فانتزی',description:'طرح نمایشی برای بررسی ظاهر فروشگاه؛ عکس و مشخصات نهایی باید توسط فروشنده ثبت شود.',image:'assets/flowers.svg',images:['assets/flowers.svg'],featured:true,status:'published',demo:true,variants:[{id:31,sku:'DEMO-FLOWER',color:'شیری',hex:'#e8ddc1',size:'سایز نمونه A',price:1650000,stock:4,published:true}]},{id:4,name:'جوراب ساده مریم‌گلی',slug:'sage-socks',category:'ساده و تک‌رنگ',description:'جای‌نگهدار تصویری؛ این محصول و موجودی صرفاً نمونه هستند.',image:'assets/sage.svg',images:['assets/sage.svg'],featured:true,status:'published',demo:true,variants:[{id:41,sku:'DEMO-SAGE',color:'سبز',hex:'#a8b99a',size:'سایز نمونه A',price:1250000,stock:7,published:true}]},{id:5,name:'جوراب کوتاه صورتی',slug:'pink-socks',category:'ساق‌کوتاه',description:'جای‌نگهدار تصویری؛ اطلاعات محصول برای نمایش مسیر خرید است.',image:'assets/pink.svg',images:['assets/pink.svg'],featured:false,status:'published',demo:true,variants:[{id:51,sku:'DEMO-PINK',color:'صورتی',hex:'#d4a7ad',size:'سایز نمونه A',price:1350000,stock:0,published:true}]}];
function save(){if(DEMO){safeStore('maro-demo-products-v1',data);safeStore('maro-demo-settings-v1',settings)}safeStore(DEMO?'maro-demo-cart':'maro-cart',cart)}
async function api(path,method='GET',body){let opts={method,headers:{Accept:'application/json','X-CSRF-TOKEN':window.MARO?.csrf||''}};if(body instanceof FormData)opts.body=body;else if(body){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}let r=await fetch('/api/'+path,opts);let j;try{j=await r.json()}catch{throw new Error('پاسخ سرور دریافت نشد؛ بدون پرداخت دوباره، وضعیت سفارش را بررسی کن.')}if(!r.ok)throw new Error(r.status===419?'نشست منقضی شده؛ صفحه را تازه کن.':Object.values(j.errors||{}).flat().join(' ')||j.message||'درخواست انجام نشد');return j}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(html,cls=''){let d=$('#modal');if(d.open)d.close();d.className=cls;d.innerHTML=html;d.setAttribute('aria-labelledby','dialog-title');document.body.style.overflow='hidden';d.showModal();d.onclick=e=>{if(e.target===d&&e.clientX>=0){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}}}
function closeModal(){if($('#modal').open)$('#modal').close();document.body.style.overflow=''}$('#modal').addEventListener('close',()=>document.body.style.overflow='');
const modalTop=t=>`<div class="modal-top"><h2 id="dialog-title">${t}</h2><button class="icon-btn" data-action="close" aria-label="بستن">${icon('close')}</button></div>`;
const safeDecode=s=>{try{return decodeURIComponent(s)}catch{return ''}};
const productHref=p=>DEMO?'#/product/'+encodeURIComponent(p.slug):'/products/'+encodeURIComponent(p.slug);
const published=()=>data.filter(p=>p.status==='published'&&p.variants.some(v=>v.published));const variants=p=>p.variants.filter(v=>v.published);const minPrice=p=>Math.min(...variants(p).map(v=>v.price));const inStock=p=>variants(p).some(v=>v.stock>0&&v.sale_enabled!==false);
function header(){return `<div class="announcement">یه جفت برای خودت، یه جفت برای کسی که دوستش داری</div><header class="header"><div class="wrap header-inner"><button class="icon-btn mobile-only" data-action="menu" aria-label="باز کردن منو">${icon('menu')}</button><a href="#/" class="wordmark" aria-label="مارو سلکت">MARO<small>S E L E C T</small></a><nav class="nav"><a href="#/shop">فروشگاه</a><a href="#/categories">دسته‌بندی‌ها</a><a href="#/about">دربارهٔ مارو</a><a href="#/track">پیگیری سفارش</a></nav><div class="tools"><button class="icon-btn" data-action="search" aria-label="جست‌وجو">${icon('search')}</button><a href="#/cart" class="icon-btn" aria-label="سبد خرید">${icon('bag')}<span class="count">${num(cart.reduce((a,b)=>a+b.qty,0))}</span></a></div></div></header>${DEMO?'<div class="demo-bar"><span class="status-dot"></span>نسخهٔ نمایشی · اطلاعات کالا نمونه است و پرداخت فعال نیست</div>':''}`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="wordmark" href="#/">MARO<small>S E L E C T</small></a><p>برای قدم‌های کوچک، برای حال‌های خوب.<br>جوراب‌هایی که به روزت رنگ می‌دهند.</p></div><div><h3>با خیال راحت انتخاب کن</h3><a href="#/shipping">روش ارسال</a><a href="#/size">راهنمای سایز</a><a href="#/returns">تعویض و مرجوعی</a><a href="#/track">پیگیری سفارش</a></div><div><h3>دنیای مارو</h3><a href="#/about">دربارهٔ ما</a><a href="#/contact">تماس با مارو</a><a href="#/terms">شرایط خرید</a><a href="#/privacy">حریم خصوصی</a>${DEMO?'':'<a href="#/admin">ورود به مدیریت</a>'}</div></div><div class="footer-bottom"><span>تمام حقوق برای مارو سلکت محفوظ است.</span><span dir="ltr">MARO SELECT · مارو سلکت</span></div></div></footer>`}
function card(p){return `<article class="product"><a class="product-image" href="${productHref(p)}"><img src="${esc(p.image)}" alt="${esc(p.name)}" width="400" height="500" loading="lazy"><span class="tag">${!inStock(p)?'ناموجود':p.image.endsWith('.svg')?'تصویر شماتیک':p.demo?'اطلاعات نمونه':'انتخاب مارو'}</span><span class="view">${icon('arrow')}</span></a><a class="product-title" href="${productHref(p)}">${esc(p.name)}</a><div class="product-meta"><span>${money(minPrice(p))}</span><div class="swatches">${[...new Set(variants(p).map(v=>v.hex))].map(c=>`<span class="swatch" style="background:${/^#[a-f\d]{6}$/i.test(c)?c:'#b87950'}"></span>`).join('')}</div></div></article>`}
function cats(){let names=[...new Set(published().map(p=>p.category))];return `<div class="categories">${names.map((n,i)=>`<a class="category" href="#/shop?category=${encodeURIComponent(n)}">${ill(({'مناسبتی':'gift','فانتزی':'cat','ساده و تک‌رنگ':'yarn','ساق‌کوتاه':'sock','ساق‌بلند':'sock','ست و بسته‌ای':'gift'})[n]||'flower')}<span>${esc(n)}</span><small>${num(published().filter(p=>p.category===n).length)} انتخاب</small></a>`).join('')}</div>`}
const faq=()=>`<div class="faq"><h2>شاید سؤال تو هم باشد</h2><details><summary>چطور سایز مناسب را انتخاب کنم؟</summary><p>راهنمای هر محصول و تنوع‌های ثبت‌شده را بررسی کن. سایزهای فعلی در پیش‌نمایش نمونه‌اند و برای خرید واقعی باید اطلاعات فروشنده تکمیل شود.</p></details><details><summary>برای خرید باید حساب بسازم؟</summary><p>نه، خرید به‌صورت مهمان انجام می‌شود. فقط اطلاعات لازم برای ارسال را وارد می‌کنی.</p></details><details><summary>هزینهٔ ارسال چطور محاسبه می‌شود؟</summary><p>هزینهٔ ارسال پیش از پرداخت در جمع سفارش نمایش داده می‌شود و بر اساس تنظیمات فروشگاه محاسبه خواهد شد.</p></details><details><summary>چطور سفارش را پیگیری کنم؟</summary><p>پس از ثبت سفارش، کد خصوصی پیگیری نمایش داده می‌شود. این کد را نگه دار و در صفحهٔ پیگیری سفارش وارد کن.</p></details></div>`;
function home(){return `<main id="main"><div class="wrap"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="tiny-bloom">${icon('flower')}</span>از مارو، با عشق به جزئیات</div><h1>${settings.banner&&settings.banner!=='یه جفت حال خوب، برای هر روز'?esc(settings.banner):'یه جفت <em>حال خوب،</em><br>برای هر روز'}</h1><p>جوراب‌های رنگی و فانتزی، برای سلیقه‌های خاص</p><div class="actions"><a class="btn" href="#/shop">دیدن جوراب‌ها ${icon('arrow')}</a><a class="btn secondary" href="#/shop?sort=new">جدیدترین‌ها</a></div><div class="hero-note">${icon('sock')}<span>جزئیات کوچکی که روزت را متفاوت می‌کنند.</span></div></div><div class="hero-art"><div class="photo one"><img src="${esc(settings.hero_image||'assets/blue.webp')}" alt="جوراب آبی با طرح خرس اسکی‌باز" width="1100" height="825" fetchpriority="high"></div><div class="photo two"><img src="assets/red.webp" alt="جوراب قرمز با طرح خرس تدی کریسمس" width="1100" height="825"></div><div class="sticker">${ill('flower')}یه جفت<br>دوست‌داشتنی</div><span class="spark" aria-hidden="true">${icon('flower')}</span><span class="thread" aria-hidden="true"></span><span class="hero-doodle" aria-hidden="true">${ill('yarn')}</span><span class="little-label">رنگی بپوش، ساده خوشحال باش</span></div></section><div class="benefits"><div class="benefit">${ill('sock')}<div>طرح‌های دوست‌داشتنی<small>از ساده تا خیال‌انگیز</small></div></div><div class="benefit">${ill('gift')}<div>خرید ساده و مهمان<small>بدون ساخت حساب کاربری</small></div></div><div class="benefit">${ill('box')}<div>پیگیری قدم‌به‌قدم<small>از ثبت سفارش تا ارسال</small></div></div></div><section class="section" id="categories"><div class="section-head"><div><h2>امروز چه حال‌وهوایی داری؟</h2><p>یه طرح برای هر سلیقه، یه رنگ برای هر روز</p></div></div>${cats()}</section><section class="section" style="padding-top:15px"><div class="section-head"><div><div class="eyebrow">انتخاب‌های تازه</div><h2>تازه به مارو رسیدن</h2></div><a class="link" href="#/shop">همهٔ جوراب‌ها ←</a></div><div class="products">${published().slice(0,4).map(card).join('')}</div></section><section class="section" style="padding-top:15px"><div class="collection"><div class="collection-copy"><div class="eyebrow">قصهٔ زمستان</div><h2>روزهای سرد،<br>انتخاب‌های رنگی</h2><p>طرح‌های زمستانی کنار رنگ‌هایی که دوستشان داریم؛ یک بهانهٔ کوچک برای عوض‌کردن حال‌وهوا.</p><a class="btn secondary" href="#/shop?category=${encodeURIComponent('مناسبتی')}">دیدن مجموعهٔ زمستانی ${icon('arrow')}</a></div><div class="collection-photo"><img src="assets/red.webp" alt="مجموعهٔ زمستانی مارو" width="1100" height="825" loading="lazy"></div></div></section><section class="section" style="padding-top:10px"><div class="section-head"><div><h2>منتخب مارو</h2><p>انتخاب‌هایی از بین طرح‌های دوست‌داشتنی</p></div><a class="link" href="#/shop">بیشتر ببین ←</a></div><div class="products">${published().filter(p=>p.featured).slice(0,4).map(card).join('')}</div></section><section class="section about"><div class="about-stamp">${icon('sock')}<span>MARO</span><small>با عشق به جزئیات</small></div><div><div class="eyebrow">قصهٔ کوچک ما</div><h2>خوشحالی، گاهی یه جفت جورابه.</h2><p>${esc(settings.about)}</p><a class="link" href="#/about">بیشتر از مارو بخوان ←</a></div></section><section class="section">${faq()}</section></div></main>`}
function shop(){let ps=published().filter(p=>(filter.category==='همه'||p.category===filter.category)&&norm(p.name+' '+p.description).includes(norm(filter.q))&&(!filter.stock||inStock(p))&&variants(p).some(v=>(!filter.color||v.color===filter.color)&&(!filter.size||v.size===filter.size)&&(!filter.stock||v.stock>0))&&(!filter.min||minPrice(p)>=Number(digits(filter.min))*10)&&(!filter.max||minPrice(p)<=Number(digits(filter.max))*10));if(filter.sort==='low')ps.sort((a,b)=>minPrice(a)-minPrice(b));if(filter.sort==='high')ps.sort((a,b)=>minPrice(b)-minPrice(a));return `<main id="main" class="wrap"><div class="page-top"><div class="breadcrumb"><a href="#/">خانه</a> / فروشگاه</div><h1>جفتِ موردعلاقه‌ات اینجاست.</h1><p>از بین رنگ‌ها و طرح‌ها، حال خوبت را انتخاب کن.</p></div><div class="toolbar"><input id="query" aria-label="جست‌وجوی محصول" placeholder="دنبال چه جورابی می‌گردی؟" value="${esc(filter.q)}"><select id="sort" aria-label="مرتب‌سازی">${[['new','جدیدترین'],['low','قیمت کمتر'],['high','قیمت بیشتر']].map(([v,n])=>`<option value="${v}" ${filter.sort===v?'selected':''}>${n}</option>`).join('')}</select><button class="btn secondary" data-action="filters">فیلترها ${icon('search')}</button><span class="muted">${num(ps.length)} محصول</span></div><div class="filter-row">${['همه',...new Set(published().map(p=>p.category))].map(c=>`<button class="chip ${c===filter.category?'active':''}" data-cat="${esc(c)}">${esc(c)}</button>`).join('')}</div><section class="section" style="padding-top:0"><div class="products">${ps.map(card).join('')}</div>${!ps.length?'<div class="empty">محصولی با این مشخصات پیدا نشد.<br><button class="btn secondary" data-action="clear-filters">پاک کردن فیلترها</button></div>':''}</section></main>`}
function product(p){selected=null;quantity=1;return `<main id="main" class="wrap"><div class="page-top"><div class="breadcrumb"><a href="#/">خانه</a> / <a href="#/shop">فروشگاه</a> / ${esc(p.name)}</div></div><div class="product-detail"><div class="gallery">${(p.images?.length?p.images:[p.image]).map(src=>`<button data-zoom="${esc(src)}" aria-label="بزرگ‌نمایی تصویر"><img src="${esc(src)}" alt="${esc(p.name)}" width="700" height="800"></button>`).join('')}</div><div class="detail-copy"><div class="eyebrow">${esc(p.category)} · MARO SELECT</div><h1>${esc(p.name)}</h1><p>${esc(p.description)}</p><div class="price" id="detail-price">${money(minPrice(p))}</div><span class="label">مدل و سایز را انتخاب کن</span><div class="options">${variants(p).map(v=>`<button class="option" data-variant="${v.id}" ${(v.stock<1||v.sale_enabled===false)?'disabled':''}>${esc(v.color)} · ${esc(v.size)}${(v.stock<1||v.sale_enabled===false)?' — ناموجود':''}</button>`).join('')}</div><div class="stock" id="variant-stock">برای مشاهدهٔ موجودی، یک تنوع انتخاب کن.</div><div class="actions"><div class="qty"><button data-qty="-1" aria-label="کاهش تعداد">−</button><span id="qty">۱</span><button data-qty="1" aria-label="افزایش تعداد">+</button></div><button class="btn" data-add="${p.id}" id="add-btn" disabled>انتخاب تنوع ${icon('bag')}</button></div>${p.demo?'<div class="notice">قیمت، موجودی و سایز این محصول نمونه است. این پیش‌نمایش برای خرید واقعی نیست.</div>':''}<details><summary>راهنمای سایز و مشخصات</summary><p>${esc(p.specifications||'اطلاعات اندازه، جنس و روش شست‌وشو هنوز توسط فروشنده تأیید نشده است.')}</p></details><details><summary>ارسال و تعویض</summary><p>هزینهٔ ارسال پیش از پرداخت مشخص می‌شود. شرایط تعویض و زمان تحویل پس از تأیید فروشنده منتشر خواهد شد.</p></details></div></div><section class="section"><div class="section-head"><h2>شاید این‌ها را هم دوست داشته باشی</h2></div><div class="products">${published().filter(x=>x.id!==p.id).slice(0,4).map(card).join('')}</div></section></main>`}
function cartItems(){return cart.map(c=>{let p=data.find(x=>x.id===c.product),v=p?.variants.find(x=>x.id===c.variant);return p&&v?{...c,p,v}:null}).filter(Boolean)}function subtotal(){return cartItems().reduce((s,c)=>s+c.v.price*c.qty,0)}function shipping(){return settings.free_above&&subtotal()>=settings.free_above?0:Number(settings.shipping)}
function totals(ship=false){return `<div class="total-row"><span>جمع کالاها</span><span>${money(subtotal())}</span></div><div class="total-row"><span>هزینهٔ ارسال</span><span>${ship?money(shipping()):'در تسویه‌حساب'}</span></div><div class="total-row final"><span>${ship?'مبلغ نهایی':'جمع سبد'}</span><span>${money(subtotal()+(ship?shipping():0))}</span></div>`}
function cartPage(){return `<main id="main" class="wrap"><div class="page-top"><h1>سبدِ حال خوبت</h1></div>${!cartItems().length?`<div class="empty">${icon('bag')}<h2>سبدت هنوز خالیه.</h2><p>یه جفت حال خوب منتظر انتخاب توئه.</p><a class="btn" href="#/shop">بریم فروشگاه ${icon('arrow')}</a></div>`:`<div class="cart-layout"><div>${cartItems().map(c=>`<div class="cart-row"><img src="${esc(c.p.image)}" alt="${esc(c.p.name)}" width="85" height="105"><div><h3>${esc(c.p.name)}</h3><p>${esc(c.v.color)} · ${esc(c.v.size)}</p><div class="qty"><button data-cart-qty="${c.variant}" data-delta="-1" aria-label="کاهش تعداد">−</button><span>${num(c.qty)}</span><button data-cart-qty="${c.variant}" data-delta="1" aria-label="افزایش تعداد">+</button></div></div><div>${money(c.v.price*c.qty)}<br><button class="remove" data-remove="${c.variant}">حذف</button></div></div>`).join('')}</div><aside class="box"><h3>خلاصهٔ سفارش</h3>${totals()}${cartValid()?`<a href="#/checkout" class="btn full">ادامهٔ خرید ${icon('arrow')}</a>`:`<div class="notice error">موجودی یا انتشار یکی از کالاها تغییر کرده؛ تعداد را اصلاح یا کالا را حذف کن.</div>`}<p class="muted" style="margin-top:15px">افزودن به سبد، موجودی را رزرو نمی‌کند. قیمت و موجودی پیش از پرداخت دوباره بررسی می‌شوند.</p></aside></div>`}</main>`}
const field=(name,label,opts={})=>`<div class="field ${opts.wide?'wide':''}"><label for="${name}">${label}</label><input id="${name}" name="${name}" ${opts.required===false?'':'required'} type="${opts.type||'text'}" autocomplete="${opts.auto||'off'}" ${opts.mode?`inputmode="${opts.mode}"`:''} maxlength="${opts.max||200}" value="${esc(checkoutDraft?.[name]||'')}"><div class="error" id="err-${name}"></div></div>`;
function checkout(){if(!cartValid())return cartPage();return `<main id="main" class="wrap"><div class="page-top"><h1>فقط چند قدم تا ثبت سفارش</h1><div class="steps"><span class="current">۱. اطلاعات ارسال</span><span>۲. بررسی سفارش</span><span>۳. پرداخت</span></div></div><div class="cart-layout"><form id="checkout-form" class="box"><h3>سفارش را کجا بفرستیم؟</h3>${DEMO?'<p class="notice">محیط نمایشی است؛ لطفاً اطلاعات واقعی وارد نکن. این فرم اطلاعات را به سرور نمی‌فرستد.</p>':''}<div class="form-grid">${field('first_name','نام',{auto:'given-name'})}${field('last_name','نام خانوادگی',{auto:'family-name'})}${field('mobile','شمارهٔ موبایل',{auto:'tel',mode:'tel',max:11})}${locationFields()}${field('address','نشانی کامل',{auto:'street-address',wide:true,max:600})}${field('postal','کدپستی ۱۰ رقمی',{auto:'postal-code',mode:'numeric',max:10})}${field('email','ایمیل (اختیاری)',{auto:'email',type:'email',required:false})}<div class="field wide"><label for="note">توضیحات سفارش (اختیاری)</label><textarea name="note" id="note" maxlength="500">${esc(checkoutDraft?.note||'')}</textarea></div></div><button class="btn full" style="margin-top:25px">بررسی سفارش ${icon('arrow')}</button></form><aside class="box"><h3>خلاصهٔ خرید</h3>${cartItems().map(c=>`<div class="total-row"><span>${esc(c.p.name)} × ${num(c.qty)}</span><span>${money(c.v.price*c.qty)}</span></div>`).join('')}${totals(true)}<p class="muted">خرید مهمان · بدون نیاز به ساخت حساب</p></aside></div></main>`}
const contentFields=[['banner','تیتر بخش اول'],['hero_image','تصویر بنر (از مسیر تصاویر همین سایت)'],['contact','اطلاعات تماس تأییدشده'],['shipping_policy','روش و زمان ارسال'],['returns_policy','شرایط تعویض و مرجوعی'],['privacy_policy','حریم خصوصی'],['terms_policy','شرایط خرید'],['size_guide','راهنمای عمومی سایز']];
const policies={about:['قصهٔ مارو',()=>settings.about],contact:['در تماس با مارو','اطلاعات تماس و نشانی پس از تأیید صاحب فروشگاه در این بخش قرار می‌گیرد. شمارهٔ موجود در تصویر مرجع منتشر نشده است.'],shipping:['روش ارسال','هزینهٔ ارسال در مرحلهٔ بررسی سفارش نمایش داده می‌شود. شرکت حمل و بازهٔ ارسال باید توسط صاحب فروشگاه تأیید و تکمیل شوند.'],size:['راهنمای سایز','سایز را از روی راهنمای اختصاصی همان محصول انتخاب کن. تا ثبت اندازه‌های واقعی توسط فروشنده، سایزهای نمونه برای خرید قابل استناد نیستند.'],returns:['تعویض و مرجوعی','سیاست تعویض و مرجوعی هنوز توسط فروشنده تأیید نشده است. فعال‌سازی فروش واقعی منوط به تکمیل و تأیید این صفحه است.'],terms:['شرایط خرید','نسخهٔ حاضر پیش‌نمایش است. قیمت، موجودی، مشخصات محصول و شرایط فروش باید پیش از فعال‌سازی خرید واقعی تأیید شوند.'],privacy:['حریم خصوصی','در نسخهٔ عملیاتی فقط اطلاعات لازم برای ثبت و ارسال سفارش دریافت می‌شود. اطلاعات کارت بانکی در فروشگاه ذخیره نمی‌شود. سیاست نگهداری و حذف اطلاعات و راه تماس مسئول فروشگاه باید پیش از انتشار نهایی تکمیل شود.']};
function track(){return `<main id="main" class="wrap"><div class="login box"><h2>سفارشت کجاست؟</h2><p class="muted">کد خصوصی پیگیری دریافت‌شده بعد از ثبت سفارش را وارد کن.</p><form id="track-form"><label class="label" for="token">کد خصوصی پیگیری</label><input id="token" name="token" required autocomplete="off" dir="ltr" minlength="32" maxlength="128"><button class="btn full" style="margin-top:18px">پیگیری سفارش</button><p class="error" id="track-error"></p></form><p class="muted">کد را گم کرده‌ای؟ پس از فعال‌شدن فروشگاه، از مسیر پشتیبانی تأییدشده برای بازیابی اقدام کن.</p></div></main>`}
function adminPage(){if(!DEMO&&!admin)return `<main id="main" class="wrap"><form id="login-form" class="login box"><h2>ورود مدیر مارو</h2>${field('email','ایمیل',{type:'email'})}${field('password','رمز عبور',{type:'password'})}${field('totp','کد تأیید دومرحله‌ای (در صورت فعال بودن)',{required:false,mode:'numeric',max:6})}<button class="btn full">ورود امن</button><p class="error" id="login-error"></p></form></main>`;let content='';if(adminTab==='dashboard')content=`<div class="metrics"><div class="metric"><span>سفارش پرداخت‌شده</span><strong>${num(window.adminStats?.paid||0)}</strong></div><div class="metric"><span>فروش تأییدشده</span><strong>${money(window.adminStats?.sales||0)}</strong></div><div class="metric"><span>تنوع کم‌موجودی</span><strong>${num(data.flatMap(p=>p.variants).filter(v=>v.stock<4).length)}</strong></div></div><div class="actions"><button class="btn" data-action="new-product">افزودن محصول +</button><button class="btn secondary" data-tab="orders">سفارش‌های جدید</button><button class="btn secondary" data-tab="low">کالاهای کم‌موجودی</button></div><div class="notice">${DEMO?'پنل نمایشی است. تغییرات محصول فقط در همین مرورگر ذخیره می‌شود و به فروشگاه واقعی متصل نیست.':'قیمت و موجودی هر تنوع را جدا مدیریت کنید. تغییرات حساس با شناسهٔ مدیر ثبت می‌شوند.'}</div><h3 style="margin-top:30px">شروع ساده</h3><p>۱. عکس و نام محصول را وارد کن.<br>۲. برای هر رنگ و سایز، قیمت و موجودی مشخص کن.<br>۳. بعد از بررسی، وضعیت را «منتشرشده» قرار بده.</p>`;if(['products','low'].includes(adminTab))content=`<button class="btn" data-action="new-product" style="margin-bottom:20px">افزودن محصول +</button><div class="table-wrap box"><table><thead><tr><th>تصویر</th><th>محصول</th><th>وضعیت</th><th>موجودی</th><th>مدیریت</th></tr></thead><tbody>${data.filter(p=>adminTab!=='low'||p.variants.some(v=>v.stock<4)).map(p=>`<tr><td><img src="${esc(p.image)}" alt=""></td><td>${esc(p.name)}</td><td>${({published:'منتشرشده',draft:'پیش‌نویس',archived:'آرشیو'})[p.status]}</td><td>${num(p.variants.reduce((a,v)=>a+v.stock,0))}</td><td><button class="btn secondary small" data-edit="${p.id}">ویرایش</button></td></tr>`).join('')}</tbody></table></div>`;if(adminTab==='orders')content=`<div class="box" id="orders-list"><div class="empty">${icon('box')}<h3>هنوز سفارشی ثبت نشده.</h3><p>سفارش‌ها و وضعیت پرداخت معتبر در این بخش نمایش داده می‌شوند.</p></div></div>`;if(adminTab==='settings')content=`<form id="settings-form" class="box"><div class="field"><label>متن معرفی برند</label><textarea name="about" required maxlength="2000" rows="4">${esc(settings.about)}</textarea></div><div class="field" style="margin-top:20px"><label>هزینهٔ ثابت ارسال (تومان)</label><input name="shipping" inputmode="numeric" required value="${settings.shipping/10}"></div><div class="field" style="margin-top:20px"><label>ارسال رایگان از مبلغ (تومان، خالی = غیرفعال)</label><input name="free_above" inputmode="numeric" value="${settings.free_above?settings.free_above/10:''}"></div><div class="notice">${DEMO?'این اعداد نمونه‌اند.':'تغییر تعرفه بر سفارش‌های ثبت‌شده اثر نمی‌گذارد.'}</div>${contentFields.map(([k,label])=>`<div class="field" style="margin-bottom:18px"><label for="setting-${k}">${label}</label><textarea id="setting-${k}" name="${k}" maxlength="4000">${esc(settings[k]||'')}</textarea></div>`).join('')}<button class="btn">ذخیرهٔ تنظیمات</button></form>`;return `<main id="main" class="wrap"><div class="admin-layout"><aside class="admin-nav">${[['dashboard','نمای کلی'],['products','محصولات'],['orders','سفارش‌ها'],['low','موجودی کم'],['settings','تنظیمات']].map(([k,t])=>`<button data-tab="${k}" class="${adminTab===k?'active':''}">${icon(({dashboard:'flower',products:'sock',orders:'box',low:'leaf',settings:'user'})[k])}${t}</button>`).join('')}${!DEMO?'<button data-action="logout">خروج امن</button>':'<button data-action="reset-demo">بازنشانی دمو</button>'}</aside><div><div class="admin-title"><h1>${({dashboard:'سلام، به مارو خوش اومدی.',products:'محصولات مارو',orders:'سفارش‌ها',low:'وقت شارژ دوباره‌ست.',settings:'تنظیمات فروشگاه'})[adminTab]}</h1><span class="muted">${DEMO?'پنل نمایشی':'مدیریت'}</span></div>${content}</div></div></main>`}
function editProduct(id){let p=id?data.find(p=>p.id===Number(id)):null;modal(`${modalTop(p?'ویرایش محصول':'محصول تازه')}<form id="product-form" data-id="${p?.id||''}"><div class="form-grid"><div class="field wide"><label>نام محصول</label><input name="name" required maxlength="120" value="${esc(p?.name||'')}"></div><div class="field"><label>دسته‌بندی</label><input name="category" required maxlength="60" value="${esc(p?.category||'فانتزی')}"></div><div class="field"><label>وضعیت</label><select name="status">${[['draft','پیش‌نویس'],['published','منتشرشده'],['archived','آرشیو']].map(([k,n])=>`<option value="${k}" ${p?.status===k?'selected':''}>${n}</option>`).join('')}</select></div><div class="field wide"><label>توضیح</label><textarea name="description" maxlength="2000">${esc(p?.description||'')}</textarea></div><div class="field wide"><label>جنس، اندازه و روش شست‌وشوی تأییدشده</label><textarea name="specifications" maxlength="2000">${esc(p?.specifications||'')}</textarea></div><div class="field wide"><label>تصاویر (JPEG، PNG، WebP؛ هر فایل تا ۵ مگابایت)</label><input name="images[]" type="file" accept="image/jpeg,image/png,image/webp" multiple><p class="muted">تصاویر جدید به انتهای گالری افزوده می‌شوند.</p>${p?.images?.length?`<div class="image-sort">${p.images.map((src,i)=>`<div class="image-sort-row" data-src="${esc(src)}"><img src="${esc(src)}" width="60" height="70" alt="تصویر ${i+1}"><button type="button" class="btn secondary small" data-image-up>بالاتر</button></div>`).join('')}</div>`:''}</div><label class="check-label"><input class="check" name="featured" type="checkbox" ${p?.featured?'checked':''}>منتخب مارو</label><div class="field wide"><label>تنوع‌ها — رنگ، سایز، قیمت تومان، موجودی</label><div id="variant-edit">${(p?.variants||[{id:null,color:'',size:'',price:0,stock:0}]).map(v=>variantFields(v)).join('')}</div><button type="button" class="btn secondary small" data-action="add-variant">افزودن تنوع</button></div><div class="field wide"><label>دلیل تغییر موجودی</label><input name="reason" required placeholder="مثلاً: ورود محمولهٔ جدید" maxlength="250"></div></div><p class="error" id="product-error"></p><button class="btn full" style="margin-top:20px">ذخیرهٔ محصول</button></form>`)}
function variantFields(v){return `<div class="variant-edit" data-id="${v.id||''}" data-revision="${v.revision??0}" style="border-bottom:1px solid var(--line);padding:12px 0;display:grid;grid-template-columns:1fr 1fr;gap:8px"><input aria-label="رنگ" placeholder="رنگ" data-v="color" required value="${esc(v.color)}"><input aria-label="سایز" placeholder="سایز" data-v="size" required value="${esc(v.size)}"><input aria-label="قیمت تومان" placeholder="قیمت تومان" inputmode="numeric" data-v="price" required value="${v.price/10}"><input aria-label="موجودی" placeholder="موجودی" inputmode="numeric" data-v="stock" required value="${v.stock}"><select aria-label="وضعیت فروش تنوع" data-v="published"><option value="true" ${v.sale_enabled!==false?'selected':''}>موجود برای فروش</option><option value="false" ${v.sale_enabled===false?'selected':''}>ناموجود / توقف فروش</option></select></div>`}
async function render(){closeModal();const raw=(location.hash||(location.pathname.startsWith('/products/')?'#/product/'+location.pathname.slice(10):'#/')).slice(1),[path,query]=raw.split('?'),params=new URLSearchParams(query||'');let body;if(path==='/shop'){if(params.has('category'))filter.category=params.get('category');if(params.has('sort'))filter.sort=params.get('sort');body=shop()}else if(path.startsWith('/product/')){let p=published().find(p=>p.slug===safeDecode(path.slice(9)));body=p?product(p):`<main class="empty" id="main"><h1>این جفت را پیدا نکردیم.</h1><a class="btn" href="#/shop">برگشت به فروشگاه</a></main>`}else if(path==='/cart')body=cartPage();else if(path==='/checkout')body=checkout();else if(path==='/track')body=track();else if(path==='/admin')body=DEMO?'<main id="main" class="wrap section"><div class="box login"><h2>پنل مدیریت در نسخه نمایشی غیرفعال است</h2><p>برای حفاظت از اطلاعات فروشگاه، مدیریت فقط روی نسخه سروری با ورود امن فعال می‌شود.</p><a class="btn" href="#/">بازگشت به فروشگاه</a></div></main>':adminPage();else if(path==='/categories')body=`<main id="main" class="wrap section"><h1>دسته‌بندی‌های مارو</h1>${cats()}</main>`;else if(policies[path.slice(1)]){let p=policies[path.slice(1)];let settingKey=({contact:'contact',shipping:'shipping_policy',returns:'returns_policy',privacy:'privacy_policy',terms:'terms_policy',size:'size_guide'})[path.slice(1)];if(settingKey&&settings[settingKey])p=[p[0],settings[settingKey]];body=`<main id="main" class="wrap policy section"><div class="breadcrumb"><a href="#/">خانه</a> / ${p[0]}</div><h1>${p[0]}</h1><p>${esc(typeof p[1]==='function'?p[1]():p[1])}</p><a class="btn secondary" href="#/shop">بازگشت به فروشگاه</a></main>`}else if(path==='/'||path==='main')body=home();else body='<main id="main" class="empty"><h1>این صفحه را پیدا نکردیم.</h1><a class="btn" href="#/shop">بازگشت به فروشگاه</a></main>';$('#app').innerHTML=header()+body+footer();if(path==='/admin'&&adminTab==='orders'&&!DEMO&&admin)loadOrders();}
window.addEventListener('hashchange',()=>{clearTimeout(debounce);render();window.scrollTo(0,0)});
document.addEventListener('click',async e=>{let b=e.target.closest('button,a');if(!b)return;try{if(b.closest('#modal')&&b.tagName==='A')closeModal();let a=b.dataset.action;if(a==='close')closeModal();if(a==='menu')modal(`${modalTop('منوی مارو')}<a href="#/" class="wordmark">MARO<small>SELECT</small></a><nav><a href="#/shop">فروشگاه</a><a href="#/categories">دسته‌بندی‌ها</a><a href="#/about">دربارهٔ مارو</a><a href="#/track">پیگیری سفارش</a><a href="#/cart">سبد خرید</a></nav>`,'drawer');if(a==='search'){filter.q='';location.hash='#/shop';setTimeout(()=>$('#query')?.focus(),80)}if(a==='filters'){modal(`${modalTop('انتخاب دقیق‌تر')}<form id="filter-form"><div class="form-grid"><div class="field"><label>از قیمت (تومان)</label><input name="min" inputmode="numeric" value="${esc(filter.min)}"></div><div class="field"><label>تا قیمت (تومان)</label><input name="max" inputmode="numeric" value="${esc(filter.max)}"></div><div class="field"><label>رنگ</label><select name="color"><option value="">همهٔ رنگ‌ها</option>${[...new Set(published().flatMap(p=>variants(p).map(v=>v.color)))].map(c=>`<option ${filter.color===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>سایز</label><select name="size"><option value="">همهٔ سایزها</option>${[...new Set(published().flatMap(p=>variants(p).map(v=>v.size)))].map(c=>`<option ${filter.size===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><label class="check-label field wide"><input class="check" name="stock" type="checkbox" ${filter.stock?'checked':''}>فقط کالاهای موجود</label></div><button class="btn full" style="margin-top:20px">نمایش نتیجه‌ها</button></form>`)}if(a==='clear-filters'){filter={q:'',category:'همه',sort:'new',stock:false,color:'',size:'',min:'',max:''};history.replaceState(null,'','#/shop');render()}if(b.dataset.cat){filter.category=b.dataset.cat;history.replaceState(null,'','#/shop');render()}if(b.dataset.variant){selected=Number(b.dataset.variant);let v=data.flatMap(p=>p.variants).find(v=>v.id===selected);quantity=1;document.querySelectorAll('[data-variant]').forEach(x=>x.classList.toggle('selected',x===b));$('#qty').textContent=num(quantity);$('#variant-stock').textContent=num(v.stock)+' عدد '+(DEMO?'موجودی نمونه':'موجود');$('#detail-price').innerHTML=money(v.price);$('#add-btn').disabled=false;$('#add-btn').innerHTML='افزودن به سبد '+icon('bag')}if(b.dataset.qty){let v=data.flatMap(p=>p.variants).find(v=>v.id===selected);quantity=Math.min(99,v?.stock||1,Math.max(1,quantity+Number(b.dataset.qty)));$('#qty').textContent=num(quantity)}if(b.dataset.add&&selected){let v=data.flatMap(p=>p.variants).find(v=>v.id===selected),c=cart.find(c=>c.variant===selected);if((c?.qty||0)+quantity>Math.min(99,v.stock))return toast('این تعداد در موجودی نیست.');if(c)c.qty+=quantity;else cart.push({product:Number(b.dataset.add),variant:selected,qty:quantity});save();$('.count').textContent=num(cart.reduce((a,c)=>a+c.qty,0));toast('به سبدِ حال خوبت اضافه شد.')}if(b.dataset.remove){cart=cart.filter(c=>c.variant!==Number(b.dataset.remove));save();render()}if(b.dataset.cartQty){let c=cart.find(c=>c.variant===Number(b.dataset.cartQty)),v=data.flatMap(p=>p.variants).find(v=>v.id===c.variant);c.qty=Math.max(1,Math.min(99,v.stock,c.qty+Number(b.dataset.delta)));save();render()}if(b.dataset.zoom)modal(`${modalTop('نمای نزدیک')}<img class="zoom" src="${esc(b.dataset.zoom)}" alt="نمای نزدیک محصول">`);if(b.dataset.tab){adminTab=b.dataset.tab;render()}if(a==='new-product')editProduct();if(b.dataset.edit)editProduct(b.dataset.edit);if(b.hasAttribute('data-image-up')){let row=b.closest('.image-sort-row');if(row.previousElementSibling)row.parentNode.insertBefore(row,row.previousElementSibling)}if(a==='add-variant')$('#variant-edit').insertAdjacentHTML('beforeend',variantFields({color:'',size:'',price:0,stock:0}));if(a==='reset-demo'){localStorage.removeItem('maro-demo-products-v1');localStorage.removeItem('maro-demo-settings-v1');localStorage.removeItem('maro-demo-cart');location.reload()}if(a==='retry-payment'){b.disabled=true;let result=await api('retry','POST',{token:window.trackingToken});modal(`${modalTop('وضعیت پرداخت')}<p>${esc(result.message)}</p>${result.redirect?`<a class="btn full" href="${esc(result.redirect)}">رفتن به درگاه</a>`:''}`)}if(a==='logout'){await api('admin/logout','POST');location.reload()}if(a==='demo-payment'){closeModal();toast('این یک پیش‌نمایش است؛ پرداخت و سفارش واقعی ثبت نشد.')}if(b.dataset.ship)shipModal(b.dataset.ship);if(a==='pay-real'){b.disabled=true;try{let result=await api('checkout','POST',{...checkoutDraft,items:cart.map(c=>({variant_id:c.variant,quantity:c.qty})),idempotency_key:window.checkoutKey});sessionStorage.setItem('maro-last-token',result.token);modal(`${modalTop('سفارش ثبت شد')}<p>کد خصوصی پیگیری را ذخیره کن:</p><input readonly dir="ltr" value="${esc(result.token)}"><p class="notice">${esc(result.message||'در حال آماده‌سازی پرداخت')}</p>${result.redirect?`<a class="btn full" href="${esc(result.redirect)}">ورود به درگاه</a>`:'<a class="btn full" href="#/track">پیگیری وضعیت</a>'}`)}catch(err){toast(err.message);b.disabled=false}}}catch(err){toast(err.message)}});
let debounce;document.addEventListener('input',e=>{if(e.target.id==='query'){filter.q=e.target.value;clearTimeout(debounce);debounce=setTimeout(()=>{if(!location.hash.startsWith('#/shop'))return;let pos=e.target.selectionStart;render();const q=$('#query');if(q){q.focus();q.setSelectionRange(pos,pos)}},250)}});document.addEventListener('change',e=>{if(e.target.id==='sort'){filter.sort=e.target.value;render()}if(e.target.id==='province'){const city=$('#city');if(city){city.innerHTML='<option value="">انتخاب شهر</option>'+locationOptions(e.target.value);city.disabled=!e.target.value}}});
document.addEventListener('submit',async e=>{e.preventDefault();let f=e.target;if(f.dataset.busy)return;f.dataset.busy='1';let submit=f.querySelector('button:not([type=button])');if(submit)submit.disabled=true;let fd=new FormData(f);try{if(f.id==='filter-form'){const lo=digits(fd.get('min')||''),hi=digits(fd.get('max')||'');if((lo&&!/^\d+$/.test(lo))||(hi&&!/^\d+$/.test(hi))||(lo&&hi&&Number(lo)>Number(hi)))throw new Error('بازهٔ قیمت معتبر وارد کن.');Object.assign(filter,Object.fromEntries(fd),{stock:fd.has('stock')});render()}if(f.id==='checkout-form'){if(!cartValid())throw new Error('سبد به بررسی مجدد نیاز دارد.');let d=Object.fromEntries(fd);d.name=[d.first_name?.trim(),d.last_name?.trim()].filter(Boolean).join(' ');if(!d.first_name?.trim()||!d.last_name?.trim())throw new Error('نام و نام خانوادگی را کامل وارد کنید.');delete d.first_name;delete d.last_name;d.mobile=digits(d.mobile);d.postal=digits(d.postal);let errors={};if(!iranLocations[d.province]||!iranLocations[d.province].includes(d.city))errors.city='استان و شهر را از فهرست انتخاب کنید.';if(!/^09\d{9}$/.test(d.mobile))errors.mobile='شمارهٔ موبایل باید ۱۱ رقم و با ۰۹ شروع شود.';if(!/^\d{10}$/.test(d.postal))errors.postal='کدپستی باید ۱۰ رقم باشد.';if(d.address.trim().length<10)errors.address='نشانی کامل‌تری وارد کن.';f.querySelectorAll('.error').forEach(el=>el.textContent='');Object.entries(errors).forEach(([k,v])=>$('#err-'+k).textContent=v);if(Object.keys(errors).length)return;checkoutDraft=d;window.checkoutKey=crypto.randomUUID();let quote=DEMO?{subtotal:subtotal(),shipping:shipping(),total:subtotal()+shipping()}:await api('quote','POST',{...d,items:cart.map(c=>({variant_id:c.variant,quantity:c.qty}))});checkoutDraft.quote_signature=quote.signature;modal(`${modalTop('بررسی نهایی سفارش')}<p>${esc(d.name)} · ${esc(d.city)}</p><p>${esc(d.address)}</p><div class="total-row"><span>جمع کالاها</span><span>${money(quote.subtotal)}</span></div><div class="total-row"><span>ارسال</span><span>${money(quote.shipping)}</span></div><div class="total-row final"><span>مبلغ نهایی</span><span>${money(quote.total)}</span></div><p class="notice">${DEMO?'پرداخت آزمایشی؛ هیچ وجهی دریافت نمی‌شود و سفارش واقعی ایجاد نمی‌شود.':'مبلغ و موجودی توسط سرور بررسی شده‌اند. هنگام شروع پرداخت دوباره کنترل می‌شوند.'}</p><button class="btn full" data-action="${DEMO?'demo-payment':'pay-real'}">${DEMO?'پایان مسیر نمایشی':'ثبت سفارش و ادامهٔ پرداخت'}</button>`)}if(f.id==='track-form'){if(DEMO)throw new Error('در پیش‌نمایش، سفارش واقعی ثبت نشده است.');let o=await api('track','POST',{token:fd.get('token')});window.trackingToken=fd.get('token');modal(`${modalTop('سفارش '+esc(o.number))}<p>پرداخت: ${esc(statusLabel(o.payment_status))}</p><p>ارسال: ${esc(statusLabel(o.fulfillment_status))}</p>${o.items.map(i=>`<div class="total-row"><span>${esc(i.name)} × ${num(i.quantity)}</span><span>${money(i.unit_price*i.quantity)}</span></div>`).join('')}<p>مبلغ نهایی: ${money(o.total)}</p>${o.shipment?`<p>کد رهگیری: <bdi>${esc(o.shipment.tracking_code)}</bdi></p>`:''}${['failed','disabled'].includes(o.payment_status)?'<button class="btn full" data-action="retry-payment">تلاش مجدد برای همین سفارش</button>':''}`)}if(f.id==='login-form'){await api('admin/login','POST',Object.fromEntries(fd));location.reload()}if(f.id==='settings-form'){let s=Object.fromEntries(fd),sh=Number(digits(s.shipping)),fr=s.free_above?Number(digits(s.free_above)):null;if(!Number.isSafeInteger(sh)||sh<0||fr!==null&&(!Number.isSafeInteger(fr)||fr<0))throw new Error('مبلغ معتبر وارد کن.');if(s.hero_image&&!/^(assets\/|\/media\/)[a-zA-Z0-9_./-]+$/.test(s.hero_image))throw new Error('مسیر تصویر باید از همین سایت باشد.');let next={...settings,...Object.fromEntries(contentFields.map(([k])=>[k,s[k]||''])),about:s.about,shipping:sh*10,free_above:fr===null?null:fr*10};if(!DEMO)await api('admin/settings','PUT',next);settings=next;save();toast('تنظیمات ذخیره شد.')}if(f.id==='product-form'){let id=Number(f.dataset.id)||Date.now(),old=data.find(p=>p.id===id),vs=[...f.querySelectorAll('.variant-edit')].map((row,i)=>{let values=Object.fromEntries([...row.querySelectorAll('[data-v]')].map(x=>[x.dataset.v,x.value]));let price=Number(digits(values.price)),stock=Number(digits(values.stock));if(!Number.isSafeInteger(price)||price<1||!Number.isSafeInteger(stock)||stock<0)throw new Error('قیمت مثبت و موجودی صحیح وارد کن.');return {id:Number(row.dataset.id)||null,revision:Number(row.dataset.revision||0),color:values.color,size:values.size,price:price*10,stock,published:true,sale_enabled:values.published==='true',sku:old?.variants.find(v=>v.id===Number(row.dataset.id))?.sku||'SKU-'+id+'-'+i,hex:old?.variants[i]?.hex||'#b87950'}});let ordered=[...f.querySelectorAll('.image-sort-row')].map(r=>r.dataset.src);fd.set('image_order',JSON.stringify(ordered));let files=fd.getAll('images[]').filter(x=>x.size);for(let file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw new Error('فقط تصویر معتبر تا ۵ مگابایت مجاز است.')}if(DEMO){vs.forEach((v,i)=>{if(!v.id)v.id=id+i+1});let images=ordered.length?ordered:(old?.images||[]);for(let file of files){let url=await new Promise((resolve,reject)=>{let r=new FileReader;r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});images.push(url)}let p={id,name:fd.get('name'),category:fd.get('category'),status:fd.get('status'),description:fd.get('description'),specifications:fd.get('specifications'),featured:fd.has('featured'),slug:old?.slug||'product-'+id,variants:vs,demo:true,images,image:images[0]||'assets/sage.svg'};if(old)data[data.indexOf(old)]=p;else data.push(p);save()}else{fd.set('variants',JSON.stringify(vs));fd.set('featured',fd.has('featured')?'1':'0');await api('admin/products'+(old?'/'+id:''),'POST',fd);data=await api('admin/products')}closeModal();render();toast('محصول ذخیره شد.')}if(f.id==='shipment-form'){await api('admin/orders/'+f.dataset.id+'/shipment','POST',Object.fromEntries(fd));closeModal();loadOrders();toast('وضعیت سفارش ثبت شد.')}}catch(err){let errorId=({'product-form':'product-error','track-form':'track-error','login-form':'login-error'})[f.id];let el=errorId?$('#'+errorId):null;if(el)el.textContent=err.message;else toast(err.message)}finally{delete f.dataset.busy;if(submit)submit.disabled=false}});
async function loadOrders(){try{let os=await api('admin/orders');$('#orders-list').innerHTML=os.length?`<div class="table-wrap"><table><tr><th>شماره</th><th>مبلغ</th><th>پرداخت</th><th>ارسال</th><th>اقدام</th></tr>${os.map(o=>`<tr><td>${esc(o.number)}</td><td>${money(o.total)}</td><td>${esc(statusLabel(o.payment_status))}</td><td>${esc(statusLabel(o.fulfillment_status))}</td><td><button class="btn secondary small" data-ship="${o.id}">مشاهده و ارسال</button></td></tr>`).join('')}</table></div>`:'<div class="empty">سفارشی ثبت نشده است.</div>'}catch(e){toast(e.message)}}
async function shipModal(id){let o=await api('admin/orders/'+id);modal(`${modalTop('سفارش '+esc(o.number))}<p>${esc(o.name)} · <bdi>${esc(o.mobile)}</bdi></p><p>${esc(o.province)}، ${esc(o.city)}، ${esc(o.address)}</p><p>کدپستی: <bdi>${esc(o.postal)}</bdi></p>${o.items.map(i=>`<p>${esc(i.name)} — ${esc(i.variant_label)} × ${num(i.quantity)}</p>`).join('')}<p>پرداخت: ${esc(statusLabel(o.payment_status))}</p><form id="shipment-form" data-id="${id}"><label class="label">وضعیت آماده‌سازی</label><select name="status"><option value="processing">در حال آماده‌سازی</option><option value="shipped">ارسال شده</option><option value="delivered">تحویل شده</option></select><label class="label">شرکت حمل</label><input name="carrier" maxlength="100"><label class="label">کد رهگیری</label><input name="tracking_code" maxlength="100"><label class="label">تاریخ ارسال</label><input type="date" name="shipped_at"><button class="btn full" style="margin-top:15px">ثبت وضعیت</button></form>`)}
async function init(){try{cart=readSaved(DEMO?'maro-demo-cart':'maro-cart',[]);if(DEMO){data=readSaved('maro-demo-products-v1',demoProducts);if(!Array.isArray(data)||!data.every(p=>p&&Array.isArray(p.variants)&&typeof p.name==='string'&&typeof p.image==='string'))data=demoProducts;settings={...settings,...readSaved('maro-demo-settings-v1',{})}}else{let r=await api('catalog');data=r.products;settings=r.settings;admin=r.admin;if(admin){data=await api('admin/products');window.adminStats=await api('admin/stats')}}data=data.map(p=>p.demo&&p.id===1&&p.image==='assets/red.webp'?{...p,name:'جوراب خرس تدی کریسمس',slug:'christmas-teddy-bear',description:'یک انتخاب قرمز و پرانرژی با طرح خرس تدی کریسمس. عکس واقعی محصول؛ مشخصات و قیمت نمونه‌اند.'}:p);cart=normalizeCart(cart);render()}catch(e){$('#app').innerHTML='<main class="empty"><h1>ارتباط برقرار نشد.</h1><p>لطفاً صفحه را دوباره بارگذاری کن.</p></main>'}}init();
